fn owned_job_call(input:RetainedTurnInput,status:OriginalOwnedJobStatus,refusal:Option<kernel::OriginalJobCallFailure>)->OriginalOwnedJobCall{OriginalOwnedJobCall{input,spent:Default::default(),work_units_spent:0,status,refusal}}
